UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 42, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 43, 7, NULL::text),(3, 171, 31, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 206, 1024, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='bca8acb1-5929-5565-9084-3d27a90be929' AND md5(a.contenido)='d8f46dc1b918178fd807faf46eb1c5cf' RETURNING a.id,md5(a.contenido) hash;